from html.parser import HTMLParser
import re, html as H

TARGETS = ['Nasdaq - US','NYSE','Shanghai Stock Exchange','Shenzhen Stock Exchange','Hong Kong Exchanges and Clearing']

class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tables=[]; self.cur=None; self.row=None; self.cell=None; self.inh3=False; self.h3=''
        self.pending_h3=None
    def handle_starttag(self,tag,attrs):
        if tag=='h3': self.inh3=True; self.h3=''
        elif tag=='table': self.cur=[]; self.pending_h3=self.h3
        elif tag=='tr' and self.cur is not None: self.row=[]
        elif tag in ('td','th') and self.row is not None: self.cell=[]
        elif tag=='br' and self.cell is not None: self.cell.append(' ')
    def handle_endtag(self,tag):
        if tag=='h3': self.inh3=False
        elif tag=='table' and self.cur is not None:
            self.tables.append((self.pending_h3,self.cur)); self.cur=None
        elif tag=='tr' and self.row is not None:
            self.cur.append(self.row); self.row=None
        elif tag in ('td','th') and self.cell is not None:
            self.row.append(re.sub(r'\s+',' ',''.join(self.cell)).strip()); self.cell=None
    def handle_data(self,d):
        if self.inh3: self.h3+=d
        if self.cell is not None: self.cell.append(d)

for f in ['march-2025','april-2025','may-2025','june-2025','july-2025']:
    s=open(f+'.html',encoding='utf-8',errors='ignore').read()
    p=P(); p.feed(s)
    print('#####',f)
    for h3,tbl in p.tables:
        if not h3 or 'Equity' not in h3: continue
        print(' --',h3.strip())
        # header rows: first non-exchange row
        for i,row in enumerate(tbl[:3]):
            print('   HDR:',row)
        for row in tbl:
            if row and row[0].strip() in TARGETS:
                print('   ROW:',row)
